    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zeros:
        return out
    # The marker is a 2x2 zero block; erase its full rows and columns,
    # preserving the distinguished color 2.
    r0, c0 = zeros[0]
    rows = {r0, r0 + 1}
    cols = {c0, c0 + 1}
    for r in range(h):
        for c in range(w):
            if (r in rows or c in cols) and out[r][c] != 2:
                out[r][c] = 0
